1	#include "bbv_emit.h"
2	
3	#include <glib.h>
4	#include <inttypes.h>
5	#include <stdio.h>
6	
7	struct BbvEmit {
8	    FILE *fp;
9	    uint64_t slice_target;
10	    uint64_t slice_acc;
11	    GHashTable *pc_to_id;  // key: int64_t* (heap), value: GUINT_TO_POINTER(bb_id)
12	    GArray    *counts;     // index: bb_id - 1, value: uint64_t
13	};
14	
15	BbvEmit *bbv_emit_new(const char *path, uint64_t slice_target)
16	{
17	    if (!path || slice_target == 0) return NULL;
18	    BbvEmit *e = g_new0(BbvEmit, 1);
19	    e->fp = fopen(path, "w");
20	    if (!e->fp) {
21	        g_free(e);
22	        return NULL;
23	    }
24	    e->slice_target = slice_target;
25	    e->slice_acc    = 0;
26	    e->pc_to_id     = g_hash_table_new_full(g_int64_hash, g_int64_equal,
27	                                            g_free, NULL);
28	    e->counts       = g_array_new(FALSE, TRUE, sizeof(uint64_t));
29	    return e;
30	}
31	
32	uint64_t bbv_emit_assign_id(BbvEmit *e, uint64_t pc)
33	{
34	    int64_t key = (int64_t) pc;
35	    gpointer val = g_hash_table_lookup(e->pc_to_id, &key);
36	    if (val) {
37	        return (uint64_t) GPOINTER_TO_UINT(val);
38	    }
39	    uint64_t new_id = (uint64_t) e->counts->len + 1;
40	    int64_t *kdup = g_new(int64_t, 1);
41	    *kdup = key;
42	    g_hash_table_insert(e->pc_to_id, kdup, GUINT_TO_POINTER((guint) new_id));
43	    uint64_t zero = 0;
44	    g_array_append_val(e->counts, zero);
45	    return new_id;
46	}
47	
48	void bbv_emit_tick(BbvEmit *e, uint64_t bb_id)
49	{
50	    if (bb_id == 0 || bb_id > (uint64_t) e->counts->len) return;
51	    uint64_t *count_ptr = &g_array_index(e->counts, uint64_t, (guint)(bb_id - 1));
52	    (*count_ptr)++;
53	    e->slice_acc++;
54	    if (e->slice_acc < e->slice_target) return;
55	
56	    // Emit one SimPoint-format row. Sparse: zero-count BBs are skipped,
57	    // mirroring the sample.bb convention.
58	    fputc('T', e->fp);
59	    int first = 1;
60	    for (guint i = 0; i < e->counts->len; i++) {
61	        uint64_t c = g_array_index(e->counts, uint64_t, i);
62	        if (c == 0) continue;
63	        if (first) {
64	            fprintf(e->fp, ":%u:%" PRIu64, i + 1, c);
65	            first = 0;
66	        } else {
67	            fprintf(e->fp, " :%u:%" PRIu64, i + 1, c);
68	        }
69	        g_array_index(e->counts, uint64_t, i) = 0;
70	    }
71	    fputc('\n', e->fp);
72	    fflush(e->fp);  // make each slice durable; the plugin may exit()
73	    e->slice_acc = 0;
74	}
75	
76	void bbv_emit_close(BbvEmit *e)
77	{
78	    if (!e) return;
79	    if (e->fp) {
80	        fclose(e->fp);
81	        e->fp = NULL;
82	    }
83	    if (e->pc_to_id) g_hash_table_destroy(e->pc_to_id);
84	    if (e->counts)   g_array_free(e->counts, TRUE);
85	    g_free(e);
86	}
