21	
22	class ResumeDriver
23	{
24	public:
25	  static constexpr uint8_t kData0      = 0x04;
26	  static constexpr uint8_t kData1      = 0x05;
27	  static constexpr uint8_t kDmcontrol  = 0x10;
28	  static constexpr uint8_t kDmstatus   = 0x11;
29	  static constexpr uint8_t kAbstractcs = 0x16;
30	  static constexpr uint8_t kCommand    = 0x17;
31	
32	  static constexpr uint16_t kCsrDpc      = 0x7B1;
33	  static constexpr uint16_t kCsrMstatus  = 0x300;
34	  static constexpr uint16_t kCsrMtvec    = 0x305;
35	  static constexpr uint16_t kCsrMcycle   = 0xB00;
36	  static constexpr uint16_t kCsrMinstret = 0xB02;
37	  static constexpr uint16_t kCsrVstart   = 0x008;
38	  static constexpr uint16_t kCsrVxsat    = 0x009;
39	  static constexpr uint16_t kCsrVxrm     = 0x00A;
40	  static constexpr uint16_t kCsrVcsr     = 0x00F;
41	  static constexpr uint16_t kCsrVtype    = 0xC21;
42	  static constexpr uint16_t kCsrVl       = 0xC20;
43	
44	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
45	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
46	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
47	
48	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
49	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
50	
51	  static constexpr uint32_t kAbstractcsBusy        = 1u << 12;
52	  static constexpr uint32_t kAbstractcsCmderrMask  = 0x7u << 8;
53	
54	  static constexpr unsigned kPollIterations = kDmiPollIterations;
55	
56	  explicit ResumeDriver(DmiBus& bus)
57	      : bus_{bus}
58	  {}
59	
60	  void resume(const hybrid_state_v1& state)
61	  {
62	    if (state.magic != HYBRID_STATE_MAGIC)
63	      throw std::runtime_error("ResumeDriver::resume: bad magic");
64	    if (state.version != HYBRID_STATE_VERSION)
65	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
66	
67	    // dmactive must transition 0->1 in its own write before any other
68	    // DMCONTROL bit is honored (RISC-V Debug Spec).
69	    bus_.write(kDmcontrol, kDmcontrolDmactive);
70	    request_halt();
71	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
72	
73	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
74	    // accepted (FS or VS == Off disables the extension and the hart NACKs
75	    // the writes). Single write covers both extensions when present.
76	    const bool fp_needs_fs = (state.flags & HYBRID_FLAG_FP)
77	                          && (state.mstatus & 0x6000u);  // FS = 13:14
78	    const bool v_needs_vs  = (state.flags & HYBRID_FLAG_V)
79	                          && (state.mstatus & 0x600u);   // VS =  9:10
80	    if (fp_needs_fs || v_needs_vs)
81	      write_csr_abstract_or_pb(kCsrMstatus, state.mstatus);
82	
83	    // FPR restore (requires mstatus.FS enabled above).
84	    if (state.flags & HYBRID_FLAG_FP) {
85	      for (uint16_t i = 0; i < 32; ++i)
86	        write_64bit_register(regno_fpr(i), state.fpr[i]);
87	    }
88	
89	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
90	    // the GPR loop overwrites x5 afterward so state is preserved).
91	    if (state.flags & HYBRID_FLAG_V) {
92	      // V data regfile: reload v0..v31 from the shared scratch region via the
93	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
94	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
95	      // the restore then overwrites with the architectural values. The sweep
96	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
97	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
98	      // register, so that -- not the runtime vlenb -- is the scratch stride.
99	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
100	                      /*load=*/true);
101	
102	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
103	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
104	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
105	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
106	      write_64bit_register(regno_gpr(5), state.vl);
107	      write_64bit_register(regno_gpr(6), state.vtype);
108	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
109	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
110	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
111	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
112	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
113	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
114	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
115	    }
116	
117	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
118	    for (uint16_t i = 1; i < 32; ++i)
119	      write_64bit_register(regno_gpr(i), state.gpr[i]);
120	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
121	
122	    write_csr_tolerant(kCsrMtvec, state.mtvec);
123	
124	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
125	    // from QEMU1's drain value. Without this, vsim's local counter starts
126	    // at zero and any cycles spent inside the ROI vanish at the QEMU2
127	    // boundary. PB fallback uses x5 as scratch; safe to overwrite here as
128	    // the GPR loop already ran.
129	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
130	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
131	
132	    clear_cmderr_if_set();
133	    request_resume();
134	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
135	                   "ResumeDriver resume");
136	  }
137	
138	private:
139	  void request_halt()
140	  {
141	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
142	  }
143	
144	  void request_resume()
145	  {
146	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
147	  }
148	
149	  void write_64bit_register(uint16_t regno, uint64_t value)
150	  {
151	    write_register_abstract(bus_, regno, value);
152	  }
153	
154	  // Abstract-first CSR write with Program Buffer fallback.
155	  // Tries an abstract register write; if the DM signals cmderr, clears it,
156	  // stages the value in scratch_gpr via abstract GPR write, then executes a
157	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
158	  // to x5 (t0) which the GPR restore loop overwrites later.
159	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
160	                                 uint8_t scratch_gpr = 5)
161	  {
162	    write_64bit_register(regno_csr(csr), value);
163	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
164	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
165	    write_64bit_register(regno_gpr(scratch_gpr), value);
166	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
167	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
168	  }
169	
170	  // Write a CSR-addressable register and clear any cmderr the DM raised.
171	  // Used for CSRs whose abstract-access support may be implementation
172	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
173	  // remaining writes.
174	  void write_csr_tolerant(uint16_t csr, uint64_t value)
175	  {
176	    write_64bit_register(regno_csr(csr), value);
177	    clear_cmderr_if_set();
178	  }
179	
180	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
181	  // is rejected until the bits are W1C-cleared. We tolerate per-register
182	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
183	  // error before resuming so the hart isn't left in a stuck state.
184	  void clear_cmderr_if_set()
185	  {
186	    const auto status = bus_.read(kAbstractcs);
187	    if ((status & kAbstractcsCmderrMask) != 0u)
188	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
189	  }
190	
191	  DmiBus& bus_;
192	};
193	
194	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
195	// via an Abstract Command. Halts-and-reads contract: caller must have the
196	// hart in the halted state. Shared by StateDrain (drain at exit), and by
197	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
198	// goes sticky after the command, the helper clears it and reports 0
199	// rather than blocking the caller -- a missing CSR mirrors as zero
200	// instead of corrupting the adjacent field.
201	inline auto read_register_64(DmiBus& bus, uint16_t regno,
202	                             const char* poll_label = "read_register_64")
203	  -> uint64_t
204	{
205	  using RD = ResumeDriver;
206	  bus.write(RD::kCommand,
207	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
208	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
209	  const auto status = bus.read(RD::kAbstractcs);
210	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
211	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
212	    return 0u;
213	  }
214	  const uint64_t lo = bus.read(RD::kData0);
215	  const uint64_t hi = bus.read(RD::kData1);
216	  return lo | (hi << 32);
217	}
