101	// deduce `Observer = NullObserver`. The default-arg form of CTAD cannot
102	// see template defaults, so spell them out as deduction guides.
103	template<typename Trigger>
104	HandoffController(Trigger, DmiBus&)
105	  -> HandoffController<Trigger, NullObserver>;
106	
107	template<typename Trigger, typename Observer>
108	HandoffController(Trigger, DmiBus&, Observer)
109	  -> HandoffController<Trigger, Observer>;
